 "content": "def transform(grid):
    """Vertically align each colored motif by its top edge, preserving x and shape."""
    h, w = len(grid), len(grid[0])
    by_color = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                by_color.setdefault(color, []).append((r, c))
    if not by_color:
        return [row[:] for row in grid]
    top = min(r for cells in by_color.values() for r, _ in cells)
    out = [[0] * w for _ in range(h)]
    for color, cells in by_color.items():
        shift = min(r for r, _ in cells) - top
        for r, c in cells:
            out[r - shift][c] = color
    return out
